S = "Hakeem Force Academy"
QS = [
(S, "Who is the current President of the United States of America?", ["Joe Biden", "Barack Obama", "Donald Trump", "Kamala Harris"], 2, "Donald Trump began his second term as the 47th President on 20 January 2025 and holds the office in October 2026.", "Joe Biden was President from January 2021 to January 2025, which is why older answers name him.", [680, 1426, 64]),
(S, "Who lives and works in the White House in Washington, D.C.?", ["The US President", "The Chief Justice", "The Speaker of the House", "The UN Secretary-General"], 0, "The White House is the official residence and workplace of the President of the United States.", "The White House has been the residence of every US President since John Adams in 1800.", [1385]),
(S, "In which year was the name Pakistan first coined and used, in the pamphlet Now or Never?", ["1930", "1933", "1940", "1947"], 1, "Choudhry Rahmat Ali and his Cambridge colleagues first used the name Pakistan in the pamphlet Now or Never, published on 28 January 1933.", "The Lahore Resolution demanding separate Muslim states was passed later, in March 1940.", [378]),
(S, "In which Hijri year was Hazrat Usman (RA) martyred?", ["30 AH", "33 AH", "35 AH", "40 AH"], 2, "Hazrat Usman (RA), the third caliph, was besieged in his house and martyred in Dhul Hijjah 35 AH (656 CE).", "He was succeeded as caliph by Hazrat Ali (RA).", [2614]),
(S, "What is the last letter of the meaningful word formed by arranging the letters UTYEAB?", ["B", "E", "U", "Y"], 3, "The letters UTYEAB can be arranged to form the word BEAUTY, whose last letter is Y.", "The word BEAUTY is made of six letters, three of which (E, A, U) are vowels.", [3685, 4186, 225]),
(S, "Al-Lat and Al-Uzza were names of what in pre-Islamic Arabia?", ["Idols (goddesses)", "Tribes of Makkah", "Wells near Makkah", "Valleys near Taif"], 0, "Al-Lat, Al-Uzza and Manat were the three chief idols worshipped by the Arabs before Islam.", "Al-Lat was worshipped at Taif and Al-Uzza near Makkah; Manat was worshipped near Madinah.", [3137, 3152]),
(S, "If 8 : 4 :: X : 16, what is the value of X?", ["8", "24", "32", "64"], 2, "8 : 4 is the ratio 2 : 1, so X : 16 must also be 2 : 1. Hence X = 16 x 2 = 32.", "In a proportion a : b :: c : d, the product of the extremes equals the product of the means (a x d = b x c).", [2334]),
(S, "If x = (1/3) y and y = 9, what is the value of x?", ["3", "6", "27", "1"], 0, "Substitute y = 9: x = (1/3) x 9 = 3.", "Multiplying by 1/3 is the same as dividing by 3.", [2445]),
(S, "If Y = 4x - 2 and x = 2, what is the value of Y?", ["4", "8", "10", "6"], 3, "Substitute x = 2: Y = 4 x 2 - 2 = 8 - 2 = 6.", "Multiplication is done before subtraction in the order of operations.", [2448]),
(S, "If y = 2x - 1 and x = 2, what is the value of y?", ["3", "5", "2", "4"], 0, "Substitute x = 2: y = 2 x 2 - 1 = 4 - 1 = 3.", "Substitution means replacing a variable by its given value.", [2450]),
(S, "What is the value of 2 + 2/2?", ["2", "3", "4", "1"], 1, "Division is done first by BODMAS: 2/2 = 1. Then 2 + 1 = 3.", "BODMAS stands for Brackets, Orders, Division, Multiplication, Addition, Subtraction.", [1206]),
(S, "What comes next in the series Z1, Y2, X3, ...?", ["W4", "V4", "W3", "U4"], 0, "The letters move backwards through the alphabet (Z, Y, X, W) while the numbers go up by 1 (1, 2, 3, 4). So the next term is W4.", "Letter pairs like this often combine a reverse alphabet with an increasing number.", [4034]),
(S, "Vehicle is to wheel as sound is to what?", ["Echo", "Waves", "Speed", "Silence"], 1, "A vehicle moves by means of wheels, and sound travels by means of waves.", "Sound needs a medium such as air, water or a solid to travel as waves.", [102]),
(S, "What does the word venerate mean?", ["To ignore", "To fear", "To regard with great respect", "To criticise"], 2, "To venerate is to regard someone or something with deep respect and reverence. Its synonyms are revere and honour.", "The adjective venerable describes a person worthy of great respect, often because of age or wisdom.", [1044, 3786, 621]),
(S, "On what date was the Treaty of Versailles signed?", ["11 November 1918", "28 June 1919", "1 September 1939", "10 January 1920"], 1, "The Treaty of Versailles was signed on 28 June 1919 in the Hall of Mirrors at the Palace of Versailles.", "It came into force on 10 January 1920, the same day the League of Nations first met.", [2887]),
(S, "What was the Treaty of Versailles?", ["A peace treaty ending World War I with Germany", "A treaty ending World War II", "An alliance between Britain and France", "A treaty founding the United Nations"], 0, "The Treaty of Versailles was the peace settlement between Germany and the Allied Powers after World War I.", "It forced Germany to accept war guilt, pay reparations and lose territory.", [4178]),
(S, "According to the commonly accepted count, how many verses (ayat) does the Holy Quran have?", ["6666", "6236", "5236", "6326"], 1, "The Hafs count most widely followed gives 6236 verses across 114 surahs.", "Counts differ slightly between recitation traditions; 6666 is a popular but not the standard figure.", [2278]),
(S, "Fill in the blank: He was very grateful that he ----- my computer promptly.", ["repairs", "repaired", "repairing", "repair"], 1, "The sentence is in the past tense (was grateful), so the past tense repaired is correct.", "Tense should stay consistent between the clauses of a sentence.", [1955]),
(S, "Who was the Viceroy of India at the time of the Partition of Bengal in 1905?", ["Lord Curzon", "Lord Minto", "Lord Mountbatten", "Lord Canning"], 0, "Lord Curzon was Viceroy from 1899 to 1905 and announced the partition of Bengal in 1905.", "The partition was annulled in 1911 under Lord Hardinge.", [4949, 701, 1474]),
(S, "Who was the first Viceroy of India?", ["Lord Canning", "Lord Curzon", "Lord Ripon", "Lord Dalhousie"], 0, "Lord Canning became the first Viceroy in 1858 after the Government of India Act transferred power from the East India Company to the Crown.", "Warren Hastings was the first Governor-General of Bengal, and Lord William Bentinck the first Governor-General of India.", [697]),
(S, "Who was the last Viceroy of British India?", ["Lord Wavell", "Lord Linlithgow", "Lord Mountbatten", "Lord Irwin"], 2, "Lord Mountbatten served as the last Viceroy from March to August 1947 and then became the first Governor-General of independent India.", "His predecessor was Lord Wavell.", [5384]),
(S, "Vienna is the capital of which country?", ["Germany", "Austria", "Switzerland", "Hungary"], 1, "Vienna is the capital and largest city of Austria on the Danube River.", "Budapest, the capital of Hungary, is also on the Danube.", [66, 3139]),
(S, "Which of the following diseases is caused by a virus?", ["Influenza", "Tuberculosis", "Malaria", "Cholera"], 0, "Influenza is caused by influenza viruses. Tuberculosis and cholera are caused by bacteria and malaria by a protozoan parasite.", "Antibiotics do not work against viral diseases.", [655]),
(S, "In which year did Prime Minister Liaquat Ali Khan make his official visit to the United States?", ["1948", "1950", "1952", "1947"], 1, "Liaquat Ali Khan visited the USA in May 1950 at the invitation of President Truman.", "This visit is seen as the start of close Pakistan-US relations.", [4217]),
(S, "Which of the following vitamins is NOT water soluble?", ["Vitamin B1", "Vitamin C", "Vitamin D", "Vitamin B6"], 2, "Vitamins A, D, E and K are fat soluble and do not dissolve in water. The B vitamins and vitamin C are water soluble.", "Fat soluble vitamins can be stored in the body, while water soluble ones are mostly excreted.", [445, 4950, 4951]),
(S, "Which party won the most seats and votes in the 1970 general elections of Pakistan?", ["Pakistan People's Party", "Awami League", "Muslim League (Qayyum)", "Jamaat-e-Islami"], 1, "The Awami League led by Sheikh Mujibur Rahman won 160 of the 300 general seats in the National Assembly, almost all in East Pakistan.", "The PPP of Z. A. Bhutto came second, winning 81 seats, all in West Pakistan.", [4809]),
(S, "How many vowels are in the letter string AEDIPOUDLEC (Aedipoudlec)?", ["4", "5", "6", "7"], 2, "The vowels are A, E, I, O, U, E, which makes 6.", "The English vowels are A, E, I, O and U.", [2282]),
(S, "How many vowels are in ASGJIOYTBUF?", ["3", "4", "5", "6"], 1, "The vowels are A, I, O and U, so there are 4. Y is counted as a consonant here.", "The English vowels are A, E, I, O and U.", [859]),
(S, "How many vowels are in AZPQTVSJFIU?", ["2", "4", "3", "5"], 2, "The vowels are A, I and U, giving 3.", "The English vowels are A, E, I, O and U.", [2285]),
(S, "How many vowels are in AdebccTEvIxyz?", ["3", "5", "6", "4"], 3, "The vowels are A, e, E and I, giving 4.", "Capital and small letters count equally.", [2287]),
(S, "In which year did the Year of the Elephant (Amul Fil) occur, the year in which the Prophet Muhammad (PBUH) was born?", ["570 CE", "610 CE", "622 CE", "632 CE"], 0, "Abraha's army marched on the Kaaba with elephants in about 570 CE, and the Prophet (PBUH) was born in the same year, about 53 years before the Hijra.", "Surah Al-Fil of the Quran describes this event.", [2720, 2610]),
(S, "At what age of the Prophet Muhammad (PBUH) was the last revelation (wahi) revealed?", ["40 years", "53 years", "60 years", "63 years"], 3, "The Prophet (PBUH) received his first revelation at 40 and the last verses shortly before his death at the age of 63.", "He passed away in 11 AH (632 CE).", [627, 4293]),
(S, "Wakhan Corridor border meets which country, separating Pakistan from it?", ["Tajikistan", "Uzbekistan", "Turkmenistan", "Kazakhstan"], 0, "The narrow Wakhan Corridor of Afghanistan separates Pakistan from Tajikistan.", "It also touches China at its eastern end.", [3140]),
(S, "After which event did Hazrat Khalid bin Waleed (RA) accept Islam?", ["Treaty of Hudaibiya", "Battle of Badr", "Battle of Uhud", "Conquest of Makkah"], 0, "Khalid bin Waleed (RA), who fought against Muslims at Uhud, accepted Islam after the Treaty of Hudaibiya in 7 AH.", "He is known as Saifullah, the Sword of Allah.", [754, 1240, 4216, 1712, 4215]),
(S, "Ali was walking towards north. He turned left, walked on, then turned right and again turned left. In which direction is he now facing?", ["North", "South", "West", "East"], 2, "Facing north, a left turn gives west; a right turn from west gives north; a left turn from north gives west again.", "A left turn is a quarter turn anticlockwise and a right turn is a quarter turn clockwise.", [1746]),
(S, "What is the walking between the hills of Safa and Marwa called in Hajj and Umrah?", ["Tawaf", "Sai", "Ramy", "Wuquf"], 1, "Sai is the seven-fold walking between Safa and Marwa, in remembrance of Hazrat Hajra (RA) searching for water for Ismail (AS).", "The Zamzam spring emerged during that event.", [4050]),
]
